        db.guardar_pago(compra['id'], pago['id'], pago.get('url_pago'))
    aplicar_estado(compra, pago['estado'])
    return {'compra_id': compra['id'], 'estado': db.compra(compra['id'])['estado']}


@router.post('/admin/conciliar-pagos', dependencies=[Depends(admin)])
def conciliar_pagos():
    ahora = reloj.ahora()
    resumen = {'aprobadas': 0, 'rechazadas': 0, 'pendientes': 0}
    for compra in db.compras_pendientes():
        try:
            if compra['pago_id']:
                pago = cobra.obtener_pago(compra['pago_id'])
            else:
                pago = cobra.buscar_por_referencia(f"{PREFIJO_REFERENCIA}{compra['id']}")
                if pago is not None:
                    db.guardar_pago(compra['id'], pago['id'], pago.get('url_pago'))
        except cobra.CobraError:
            pago = False
        if pago:
            aplicar_estado(compra, pago['estado'])
        elif pago is None and not compra['pago_id'] and ahora - db.a_fecha(compra['creada']) >= ESPERA_PAGO:
            db.cerrar_compra(compra['id'], 'rechazada', sin_pago=True)
        final = db.compra(compra['id'])['estado']
        clave = {'aprobada': 'aprobadas', 'rechazada': 'rechazadas'}.get(final, 'pendientes')
        resumen[clave] += 1
    return resumen


